# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety-gated target tracking with steering and scan hysteresis."""
    memory = dict(memory or {})

    state = memory.get("state", "IDLE")
    last_action = memory.get("last_action", "")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_age = int(memory.get("scan_age", 0))
    visible_age = int(memory.get("visible_age", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Safety has absolute priority.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = visible and target_confidence >= 0.55 and identity_confidence >= 0.60

    if not confirmed:
        memory["visible_age"] = 0
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            # Briefly hold position, then scan persistently in one direction.
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            scan_age += 1
            if scan_age >= 3:
                scan_direction = (
                    "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
                )
                scan_age = 0
            memory["scan_direction"] = scan_direction
            memory["scan_age"] = scan_age
            return emit(scan_direction, 0.75, "REACQUIRE")

        scan_age += 1
        if scan_age >= 3:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            scan_age = 0
        memory["scan_direction"] = scan_direction
        memory["scan_age"] = scan_age
        return emit(scan_direction, 0.72, "SEARCH")

    memory["visible_age"] = min(3, visible_age + 1)
    memory["scan_age"] = 0
    memory["scan_direction"] = scan_direction

    # Require a short-lived track before committing to motion.
    if track_age < 2 or memory["visible_age"] < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading_error <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        action = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        return emit(action, 0.88, "APPROACH")

    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    # Strong bearing evidence wins; a narrower deadband prevents flip-flopping.
    if bearing < -12.0 and left:
        action = "VEER_LEFT"
    elif bearing > 12.0 and right:
        action = "VEER_RIGHT"
    elif abs(bearing) <= 8.0 and center:
        action = "FORWARD"
    elif 8.0 < bearing <= 12.0 and last_action == "VEER_RIGHT" and right:
        action = "VEER_RIGHT"
    elif -12.0 <= bearing < -8.0 and last_action == "VEER_LEFT" and left:
        action = "VEER_LEFT"
    elif center:
        action = "FORWARD"
    elif bearing < 0.0 and left:
        action = "VEER_LEFT"
    elif bearing > 0.0 and right:
        action = "VEER_RIGHT"
    elif left:
        action = "VEER_LEFT"
    elif right:
        action = "VEER_RIGHT"
    else:
        return emit("STOP", 0.98, "STOPPED")

    return emit(action, 0.90 if action == "FORWARD" else 0.86, "APPROACH")
# EVOLVE-BLOCK-END
